package com.hs.listing.model; import com.hs.common.persistence.BaseEntity; import com.hs.listing.model.constant.ListingEnums.MediaType; import com.hs.storage.model.StorageObject; import jakarta.persistence.*; import lombok.*; import java.util.UUID;
@Entity @Table(name="listing_media") @Getter @Setter @NoArgsConstructor public class ListingMedia extends BaseEntity { @Id @Column(length=36) private String id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="listing_id") private Listing listing; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="storage_object_id") private StorageObject storageObject; @Enumerated(EnumType.STRING) @Column(name="media_type",nullable=false) private MediaType mediaType; @Column(name="sort_order",nullable=false) private Integer sortOrder; @Column(name="is_cover",nullable=false) private boolean cover; @Column(name="media_url",length=2048) private String mediaUrl; @PrePersist void pre(){if(id==null)id=UUID.randomUUID().toString();} }
